    internal sealed partial class MergeWindow {
        internal sealed class MergeBoard : ScrollableControl {
            sealed class Card {internal MergeGroup Group;internal MergePage Page;internal Rectangle Bounds;internal bool Header;}
            sealed class Drop {internal MergeGroup Group;internal int Index;internal Rectangle Line;internal string Hint;}
            readonly MergePlan plan;
