            readonly List<Rectangle> dividers=new List<Rectangle>();
            readonly Dictionary<string,Bitmap> thumbnails=new Dictionary<string,Bitmap>();
            readonly Queue<string> thumbOrder=new Queue<string>();
            readonly HashSet<MergePage> selectedPages=new HashSet<MergePage>();
            readonly Timer scroll=new Timer{Interval=60};
            readonly ToolTip tips=new ToolTip{InitialDelay=450,ReshowDelay=100,AutoPopDelay=12000,ShowAlways=true};
            static readonly Color InsertColor=Color.FromArgb(28,132,217);
            const int Gap=20,GroupGap=24;
            Card selected,dragged;
            Drop drop;
            MergeGroup hoverGroup;
            int hoverAt;
            Point down,last;
            bool arranging,selectedAsGroup,dragAsGroup;
            internal int CardWidth=120;
            internal event EventHandler Changed;
            internal MergeBoard(MergePlan data){plan=data;DoubleBuffered=true;AutoScroll=true;BackColor=Color.FromArgb(245,247,250);TabStop=true;AccessibleName=UiText.Get("合并页面缩略图");scroll.Tick+=ScrollDrag;}
            internal void Rebuild(){if(arranging)return;arranging=true;try{
                    var oldSelected=selected;var oldDragged=dragged;cards.Clear();dividers.Clear();int gap=Gap,w=CardWidth+24,h=Math.Max(CardWidth*4/3+72,CardWidth*4/3+Font.Height*2+26),right=Math.Max(gap+w,ClientSize.Width-SystemInformation.VerticalScrollBarWidth-gap),x=gap,y=gap;Card previous=null;
                    foreach(var group in plan.Groups){if(previous!=null)x+=GroupGap;int start=cards.Count;if(group.Expanded&&group.Pages.Count>0){for(int i=0;i<group.Pages.Count;i++)AddCard(new Card{Group=group,Page=group.Pages[i],Header=i==0},ref x,ref y,w,h,right,gap);}else AddCard(new Card{Group=group,Header=true},ref x,ref y,w,h,right,gap);var header=cards[start];if(previous!=null){if(previous.Bounds.Top==header.Bounds.Top)dividers.Add(new Rectangle((previous.Bounds.Right+header.Bounds.Left)/2,header.Bounds.Top-2,1,h+4));else{dividers.Add(new Rectangle(previous.Bounds.Right+gap/2,previous.Bounds.Top-2,1,h+4));dividers.Add(new Rectangle(header.Bounds.Left-gap/2,header.Bounds.Top-2,1,h+4));}}previous=cards[cards.Count-1];}
                    if(previous!=null)dividers.Add(new Rectangle(previous.Bounds.Right+gap/2,previous.Bounds.Top-2,1,h+4));AutoScrollMinSize=new Size(0,cards.Count==0?0:y+h+gap);
                    var live=new HashSet<MergePage>(plan.AllPages());selectedPages.RemoveWhere(delegate(MergePage p){return !live.Contains(p);});selected=Find(oldSelected,selectedAsGroup);dragged=Find(oldDragged,dragAsGroup);if(dragged!=null)UpdateDrop(last);else SetDrop(null);Invalidate();if(Changed!=null)Changed(this,EventArgs.Empty);
                }finally{arranging=false;}}
            void AddCard(Card card,ref int x,ref int y,int width,int height,int right,int gap){if(x+width>right){x=gap;y+=height+gap;}card.Bounds=new Rectangle(x,y,width,height);cards.Add(card);x+=width+gap;}
            Card Find(Card old,bool group){if(old==null)return null;foreach(var card in cards)if(group?old.Group==card.Group:old.Page!=null?old.Page==card.Page:old.Group==card.Group&&card.Page==null)return card;return null;}
            internal void ResetSelection(){EndDrag();selected=null;selectedAsGroup=false;selectedPages.Clear();Rebuild();}
            protected override void OnResize(EventArgs e){base.OnResize(e);if(plan!=null)Rebuild();}
            Card Hit(Point point){point.Offset(-AutoScrollPosition.X,-AutoScrollPosition.Y);foreach(var card in cards)if(card.Bounds.Contains(point))return card;return null;}
            Card Nearest(Point point){Card best=null;long distance=long.MaxValue;foreach(var card in cards){var r=card.Bounds;int dy=point.Y<r.Top?r.Top-point.Y:point.Y>r.Bottom?point.Y-r.Bottom:0,dx=point.X<r.Left?r.Left-point.X:point.X>r.Right?point.X-r.Right:0;long score=(long)dy*100000+dx;if(score<distance){best=card;distance=score;}}return best;}
            Rectangle Marker(Card card,bool after){return new Rectangle(after?card.Bounds.Right+Gap/2:card.Bounds.Left-Gap/2,card.Bounds.Top,1,card.Bounds.Height);}
            Rectangle Toggle(Card card){return card.Header?new Rectangle(card.Bounds.X+5,card.Bounds.Y+7,16,16):Rectangle.Empty;}
            bool FileTitle(Card card,Point point){point.Offset(-AutoScrollPosition.X,-AutoScrollPosition.Y);return card.Page==null||card.Header&&point.Y<card.Bounds.Top+32;}
            string PageLabel(MergePage page){return page.Name+" · "+String.Format(UiText.Get("原第 {0} 页"),page.Index+1);}
            void UpdateDrop(Point point){if(dragged==null||cards.Count==0||!ClientRectangle.Contains(point)){SetDrop(null);return;}point.Offset(-AutoScrollPosition.X,-AutoScrollPosition.Y);var card=Nearest(point);if(card==null){SetDrop(null);return;}bool after=point.X>=card.Bounds.Left+card.Bounds.Width/2;var group=card.Group;
                if(dragAsGroup){int first=cards.FindIndex(delegate(Card c){return c.Group==group;}),end=cards.FindLastIndex(delegate(Card c){return c.Group==group;}),at=cards.IndexOf(card);bool tail=(at-first)*2+(after?1:0)>=end-first+1;int index=plan.Groups.IndexOf(group)+(tail?1:0);SetDrop(new Drop{Group=group,Index=index,Line=Marker(tail?cards[end]:cards[first],tail),Hint=String.Format(UiText.Get(tail?"移动文件到 {0} 之后":"移动文件到 {0} 之前"),group.Name)});return;}
                int insert;Rectangle line;if(card.Page==null){insert=after?group.Pages.Count:0;line=Marker(card,insert>0||group.Pages.Count==0);}else{if(card.Header&&point.Y<card.Bounds.Top+32)after=false;insert=group.Pages.IndexOf(card.Page)+(after?1:0);line=Marker(card,after);}
                string position=insert==group.Pages.Count?UiText.Get("末尾"):String.Format(UiText.Get("在 {0} 之前"),PageLabel(group.Pages[insert]));string hint=String.Format(UiText.Get("插入到 {0}：{1}"),group.Name,position);if(!group.Expanded&&group.Pages.Count>0)hint+=" · "+UiText.Get("停留可展开");SetDrop(new Drop{Group=group,Index=insert,Line=line,Hint=hint});}
            void SetDrop(Drop value){drop=value;AccessibleDescription=value==null?"":value.Hint;var hover=value!=null&&dragged!=null&&!dragAsGroup&&!value.Group.Expanded?value.Group:null;if(hover!=hoverGroup){hoverGroup=hover;hoverAt=Environment.TickCount;}}
            void ScrollDrag(object sender,EventArgs args){if(dragged==null)return;int edge=28,delta=last.Y<edge?-28:last.Y>ClientSize.Height-edge?28:0;if(delta!=0&&last.X>=0&&last.X<ClientSize.Width){int old=AutoScrollPosition.Y;AutoScrollPosition=new Point(0,Math.Max(0,-old+delta));if(old!=AutoScrollPosition.Y)UpdateDrop(last);}if(hoverGroup!=null&&unchecked(Environment.TickCount-hoverAt)>700){hoverGroup.Expanded=true;hoverGroup=null;Rebuild();}Invalidate();}
            Bitmap Thumb(MergePage page){string key=page.Source.Handle.ToInt64()+":"+page.Index+":"+page.Rotation;Bitmap image;if(thumbnails.TryGetValue(key,out image))return image;var size=page.Source.PageSize(page.Index);if((page.Rotation&1)!=0)size=new SizeF(size.Height,size.Width);float scale=Math.Min(180/size.Width,220/size.Height);image=page.Source.Render(page.Index,Math.Max(1,(int)(size.Width*scale)),Math.Max(1,(int)(size.Height*scale)),page.Rotation);thumbnails.Add(key,image);thumbOrder.Enqueue(key);while(thumbnails.Count>64){string oldest=thumbOrder.Dequeue();thumbnails[oldest].Dispose();thumbnails.Remove(oldest);}return image;}
            protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(cards.Count==0){TextRenderer.DrawText(e.Graphics,UiText.Get("将 PDF 或图片拖到这里\n展开文件组后，可拖动页面调整顺序"),Font,ClientRectangle,Color.DimGray,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);return;}var state=e.Graphics.Save();e.Graphics.TranslateTransform(AutoScrollPosition.X,AutoScrollPosition.Y);
                using(var pen=new Pen(Color.FromArgb(130,146,164),2))foreach(var divider in dividers)e.Graphics.DrawLine(pen,divider.Left,divider.Top,divider.Left,divider.Bottom);
                foreach(var card in cards){var r=card.Bounds;if(r.Bottom+AutoScrollPosition.Y<0||r.Top+AutoScrollPosition.Y>Height)continue;bool active=selected!=null&&(selectedAsGroup?card.Group==selected.Group:card.Page!=null&&selectedPages.Contains(card.Page)),destination=drop!=null&&drop.Group==card.Group&&card.Header;using(var brush=new SolidBrush(active?Color.FromArgb(220,237,251):destination?Color.FromArgb(231,243,253):card.Page==null?Color.FromArgb(236,241,247):Color.White))e.Graphics.FillRectangle(brush,r);using(var pen=new Pen(active||destination?InsertColor:Color.FromArgb(220,225,232),active||destination?2:1))e.Graphics.DrawRectangle(pen,r);
                    Rectangle imageBox=new Rectangle(r.X+12,r.Y+34,r.Width-24,r.Height-72);var page=card.Page??(card.Group.Pages.Count>0?card.Group.Pages[0]:null);if(page!=null)try{var image=Thumb(page);float scale=Math.Min((float)imageBox.Width/image.Width,(float)imageBox.Height/image.Height);var dest=new Rectangle(imageBox.X+(imageBox.Width-(int)(image.Width*scale))/2,imageBox.Y+(imageBox.Height-(int)(image.Height*scale))/2,(int)(image.Width*scale),(int)(image.Height*scale));if(card.Page==null){e.Graphics.FillRectangle(Brushes.LightGray,dest.X+4,dest.Y-4,dest.Width,dest.Height);e.Graphics.FillRectangle(Brushes.WhiteSmoke,dest.X+2,dest.Y-2,dest.Width,dest.Height);}e.Graphics.DrawImage(image,dest);}catch{}
                    if(card.Header){var toggle=Toggle(card);using(var b=new SolidBrush(Color.FromArgb(225,237,247)))e.Graphics.FillRectangle(b,toggle);using(var p=new Pen(Color.FromArgb(97,126,151)))e.Graphics.DrawRectangle(p,toggle);int cx=toggle.X+8,cy=toggle.Y+8;e.Graphics.DrawLine(Pens.SteelBlue,cx-4,cy,cx+4,cy);if(!card.Group.Expanded)e.Graphics.DrawLine(Pens.SteelBlue,cx,cy-4,cx,cy+4);}
                    string title=card.Header?card.Group.Name:card.Page.Name;string label=card.Page==null?String.Format(UiText.Get("{0} 页"),card.Group.Pages.Count):String.Format(UiText.Get("页面 {0}"),card.Page.Index+1)+(card.Page.Rotation==0?"":" ↻");if(card.Page!=null&&TextRenderer.MeasureText(label,Font).Width>r.Width-8)label=(card.Page.Index+1).ToString()+(card.Page.Rotation==0?"":" ↻");int inset=card.Header?26:6;var textFlags=TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine|TextFormatFlags.PreserveGraphicsTranslateTransform|TextFormatFlags.NoPrefix;TextRenderer.DrawText(e.Graphics,title,Font,new Rectangle(r.X+inset,r.Y+4,r.Width-inset-6,28),Color.FromArgb(35,57,78),textFlags);TextRenderer.DrawText(e.Graphics,label,Font,new Rectangle(r.X+4,r.Bottom-32,r.Width-8,28),Color.DimGray,textFlags|TextFormatFlags.HorizontalCenter);}
                if(drop!=null){var r=drop.Line;using(var pen=new Pen(InsertColor,3)){e.Graphics.DrawLine(pen,r.Left,r.Top,r.Left,r.Bottom);e.Graphics.DrawLine(pen,r.Left-5,r.Top,r.Left+5,r.Top);e.Graphics.DrawLine(pen,r.Left-5,r.Bottom,r.Left+5,r.Bottom);}}e.Graphics.Restore(state);
                if(drop!=null){int width=Math.Min(Math.Max(120,ClientSize.Width-24),TextRenderer.MeasureText(drop.Hint,Font).Width+20),height=Font.Height+16;int x=Math.Max(6,Math.Min(ClientSize.Width-width-6,last.X+14)),y=last.Y+22;if(y+height>ClientSize.Height)y=Math.Max(6,last.Y-height-14);var badge=new Rectangle(x,y,width,height);using(var b=new SolidBrush(Color.FromArgb(247,252,255)))e.Graphics.FillRectangle(b,badge);using(var pen=new Pen(InsertColor))e.Graphics.DrawRectangle(pen,badge);badge.Inflate(-8,-4);TextRenderer.DrawText(e.Graphics,drop.Hint,Font,badge,Color.FromArgb(22,91,146),TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPrefix);}}
            protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;Focus();var hit=Hit(e.Location);var content=e.Location;content.Offset(-AutoScrollPosition.X,-AutoScrollPosition.Y);if(hit!=null&&hit.Header&&Toggle(hit).Contains(content)){EndDrag();selected=hit;selectedAsGroup=true;selectedPages.Clear();hit.Group.Expanded=!hit.Group.Expanded;Rebuild();return;}bool group=hit!=null&&FileTitle(hit,e.Location);if(hit!=null&&!group){if((ModifierKeys&Keys.Control)!=0){if(!selectedPages.Add(hit.Page))selectedPages.Remove(hit.Page);}else if((ModifierKeys&Keys.Shift)!=0&&selected!=null){int a=Math.Max(0,cards.IndexOf(selected)),b=cards.IndexOf(hit);for(int i=Math.Min(a,b);i<=Math.Max(a,b);i++)if(cards[i].Page!=null)selectedPages.Add(cards[i].Page);}else if(!selectedPages.Contains(hit.Page)){selectedPages.Clear();selectedPages.Add(hit.Page);}}else selectedPages.Clear();selected=hit;selectedAsGroup=group;down=last=e.Location;if(selected!=null)Capture=true;Invalidate();}
            protected override void OnMouseDoubleClick(MouseEventArgs e){base.OnMouseDoubleClick(e);if(e.Button!=MouseButtons.Left)return;var card=Hit(e.Location);if(card!=null&&card.Page==null){EndDrag();card.Group.Expanded=true;Rebuild();}}
            protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);last=e.Location;if(!Capture||selected==null){var card=Hit(e.Location);string hint=card==null?"":FileTitle(card,e.Location)?card.Group.Name+" · "+String.Format(UiText.Get("{0} 页"),card.Group.Pages.Count)+"\n"+UiText.Get("拖动文件名可移动整个文件；＋/－展开或收起。") :PageLabel(card.Page)+"\n"+String.Format(UiText.Get("所在文件组：{0}"),card.Group.Name);if(tips.GetToolTip(this)!=hint)tips.SetToolTip(this,hint);return;}if(dragged==null&&(Math.Abs(e.X-down.X)>SystemInformation.DragSize.Width/2||Math.Abs(e.Y-down.Y)>SystemInformation.DragSize.Height/2)&&(selectedAsGroup||selectedPages.Count>0)){dragged=selected;dragAsGroup=selectedAsGroup;tips.Hide(this);Cursor=Cursors.SizeAll;scroll.Start();}if(dragged!=null){UpdateDrop(e.Location);Invalidate();}}
            protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(e.Button!=MouseButtons.Left)return;Card source=dragged;bool group=dragAsGroup;if(source!=null)UpdateDrop(e.Location);var destination=drop;var moving=Selection();EndDrag();if(source!=null&&destination!=null){if(group)plan.MoveGroup(source.Group,destination.Index);else plan.MovePages(moving,destination.Group,destination.Index);Rebuild();}Invalidate();}
            void EndDrag(){dragged=null;dragAsGroup=false;SetDrop(null);scroll.Stop();if(Capture)Capture=false;Cursor=Cursors.Default;Invalidate();}
            protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(!Capture)EndDrag();}
            internal List<MergePage> Selection(){var pages=new List<MergePage>();foreach(var p in plan.AllPages())if(selected!=null&&(selectedAsGroup?selected.Group.Pages.Contains(p):selectedPages.Contains(p)))pages.Add(p);return pages;}
            internal void Rotate(){if(selected==null)return;var pages=Selection();plan.Change(delegate{foreach(var page in pages)page.Rotation=(page.Rotation+1)%4;});Rebuild();}
            internal void Duplicate(){var pages=Selection();if(pages.Count==0||plan.Count+pages.Count>10000)return;plan.Change(delegate{foreach(var p in pages){var group=plan.Owner(p);group.Pages.Insert(group.Pages.IndexOf(p)+1,new MergePage{Source=p.Source,Name=p.Name,Index=p.Index,Rotation=p.Rotation});group.Expanded=true;}});ResetSelection();}
            internal void Delete(){if(selected==null)return;plan.Change(delegate{if(!selectedAsGroup){foreach(var p in Selection())plan.Owner(p).Pages.Remove(p);}else plan.Groups.Remove(selected.Group);});ResetSelection();}
            protected override bool ProcessCmdKey(ref Message msg,Keys keys){if(keys==Keys.Delete){Delete();return true;}if(keys==(Keys.Control|Keys.Z)){plan.Undo();ResetSelection();return true;}if(keys==(Keys.Control|Keys.Y)){plan.Redo();ResetSelection();return true;}if(keys==Keys.Escape&&Capture){EndDrag();return true;}return base.ProcessCmdKey(ref msg,keys);}
            protected override void Dispose(bool disposing){if(disposing){scroll.Dispose();tips.Dispose();foreach(var image in thumbnails.Values)image.Dispose();thumbnails.Clear();}base.Dispose(disposing);}
        }
